	@Test
	void interruptedDictionaryAdmissionReturnsReservedTripleReaders(@TempDir File directory) throws Exception {
		String previousPinning = System.getProperty(PINNING_PROPERTY);
		System.setProperty(PINNING_PROPERTY, "true");
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc"));
		store.init();
		// startup maintenance briefly holds ordinary readers; the pools are measured only once it is quiescent
		LmdbTestUtil.awaitBackgroundMaintenance(store, 30, TimeUnit.SECONDS);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		List<TxnManager.Txn> fillers = new ArrayList<>();
		CountDownLatch finished = new CountDownLatch(1);
		try (SailConnection reader = store.getConnection()) {
			TxnManager triples = store.getBackingStore().getTripleStore().getTxnManager();
			TxnManager dictionary = ((ValueStore) store.getValueFactory()).getTxnManager();
			int availableTriples = triples.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			int availableDictionary = dictionary.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			for (TxnManager.Txn filler : dictionary.createReadTxnPinnedFamily(availableDictionary, () -> 0L)) {
				fillers.add(filler);
			}
			AtomicReference<Thread> acquiring = new AtomicReference<>();
			AtomicReference<RuntimeException> failure = new AtomicReference<>();
			AtomicReference<SailDatasetSnapshot> remainingContext = new AtomicReference<>();
			CountDownLatch started = new CountDownLatch(1);
			Future<?> pendingRead = executor.submit(() -> {
				acquiring.set(Thread.currentThread());
				started.countDown();
				try (CloseableIteration<? extends Statement> ignored = reader.getStatements(null, null, null, true)) {
					throw new AssertionError("Dictionary admission must wait while every reader is held");
				} catch (RuntimeException interrupted) {
					failure.set(interrupted);
				} finally {
					remainingContext.set(SailDatasetSnapshot.current());
					finished.countDown();
				}
			});
			assertTrue(started.await(DIAGNOSTIC_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			awaitReaderAdmission(acquiring.get());
			assertEquals(availableTriples - 1, triples.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
			assertTrue(pendingRead.cancel(true));
			assertTrue(finished.await(DIAGNOSTIC_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			assertTrue(failure.get() instanceof SailException);
			assertNull(remainingContext.get());
			assertEquals(availableTriples, triples.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
			assertEquals(Long.MAX_VALUE, triples.minPinnedSnapshotRevision());
		} finally {
			executor.shutdownNow();
			for (TxnManager.Txn filler : fillers) {
				filler.close();
			}
			assertTrue(executor.awaitTermination(DIAGNOSTIC_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			store.shutDown();
			restorePinning(previousPinning);
		}
	}

	@Test
	void failedRootAcquisitionReleasesReadersBeforeOnePairedRetry(@TempDir File directory) throws Exception {
		String previousPinning = System.getProperty(PINNING_PROPERTY);
		System.setProperty(PINNING_PROPERTY, "true");
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc"));
		store.init();
		// startup maintenance briefly holds ordinary dictionary readers; one admitted between the samples below and the
		// failed acquisition would read as a leaked reader
		LmdbTestUtil.awaitBackgroundMaintenance(store, 30, TimeUnit.SECONDS);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			TxnManager triples = store.getBackingStore().getTripleStore().getTxnManager();
			TxnManager dictionary = ((ValueStore) store.getValueFactory()).getTxnManager();
			int availableTriples = triples.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			int availableDictionary = dictionary.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			InterleavingGate gate = new InterleavingGate();
			SnapshotSailStore roots = new SnapshotSailStore(
					interleavingStore(store.getBackingStore(), gate), LinkedHashModel::new);
			Future<?> retry = executor.submit(() -> {
				try (SailDatasetSnapshot.Scope ignored = SailDatasetSnapshot.open();
						SailSource explicit = roots.getExplicitSailSource();
						SailSource inferred = roots.getInferredSailSource()) {
					gate.failInferredAcquisition.set(true);
					assertThrows(SailException.class, () -> explicit.dataset(IsolationLevels.SNAPSHOT));
					assertEquals(availableTriples, triples.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
					assertEquals(availableDictionary, dictionary.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
					assertEquals(Long.MAX_VALUE, triples.minPinnedSnapshotRevision());
					assertEquals(Long.MAX_VALUE, dictionary.minPinnedSnapshotRevision());
					TxnManager.Txn[] fillers = triples.createReadTxnPinnedFamily(availableTriples - 1, () -> 0L);
					TxnManager.Txn[] dictionaryFillers = dictionary
							.createReadTxnPinnedFamily(availableDictionary - 1, () -> 0L);
					try (SailDataset acquired = explicit.dataset(IsolationLevels.SNAPSHOT)) {
						assertEquals(0, acquired.getStatementCount(null, null, null));
						assertEquals(0, triples.availableReadTxnSlots(TxnManager.POOL_SIZE, 0),
								"The retry must consume exactly one paired triple reader");
						assertEquals(0, dictionary.availableReadTxnSlots(TxnManager.POOL_SIZE, 0),
								"The retry must consume exactly one paired dictionary reader");
					} finally {
						for (TxnManager.Txn filler : fillers) {
							filler.close();
						}
						for (TxnManager.Txn filler : dictionaryFillers) {
							filler.close();
						}
					}
				}
				return null;
			});
			retry.get(DIAGNOSTIC_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			assertEquals(availableTriples, triples.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
			assertEquals(availableDictionary, dictionary.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(DIAGNOSTIC_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			store.shutDown();
			restorePinning(previousPinning);
		}
	}

